/* cppi::b9c64753e58785786e3aca7a11eb961068a111e0657dfa4e604f91dbb1275ad5 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-07' and end_date = '2025-05-07')
and start_date = '2025-05-07' and end_date = '2025-05-07'

/* cppi::60b799e08eab492aaf67804b51428299ebb91fd4f1b3098c69a469efd3c48566 */
select cppib_sec_id , bloomberg_unique_id , cusip, sedol, isin, ticker from asset.asset_security_identifiers asi where business_date = date '2025-06-18' and cppib_sec_id = 29277068
LIMIT 200

/* cppi::e467e98d9cddbd0bbec2d2321896cc91d8c2b30c4696056f76c58b3e4c0128b3 */
SELECT COUNT(*) FROM ( 
    SELECT *
    FROM holdings.tfm_bp_analytics
 ) t

/* cppi::5c0dbb9085b51684fbb59c5acaae4bf4aab7832438cc6b9073b742eb511e43a8 */
SELECT "SUBCOL" AS "COL"
FROM (
  SELECT 1 AS "SUBCOL"
) "SUBQUERY"
GROUP BY 1

/* cppi::0703e8434d42ff28d9317a5f60423704a8fb6585db6d3bec144c7c84f916348e */
