/* cppi::e47dd9c5d12a9440cc7bf4181d297ac9b184e0d4b573c872703f3843b7ef5aa3 */
select trade_date, business_date, changed_date, abor_transaction_number, cost_or_tax_present, transaction_cancellation_flag, rn
from (
    SELECT *,
           ROW_NUMBER() OVER (
               PARTITION BY scd_transaction_number_primary_key
						order by
							changed_date desc -- change date is actual loaded date so use this to get the latest data.
           ) AS rn
    FROM trades_deals.scd_transactions
    WHERE accounting_framework_id = 'PCLFWKMAIN'
